// These are observations of the actual paid state, not a second dispatch model.
struct ProductiveCoverage {
    J roles=J::object();std::set<unsigned> moving;std::set<std::uint64_t> accepted_performers,granted_venue_walkers,retired_performers,retired_venue_walkers;
    std::map<std::uint64_t,sim::CourierPhase> previous_phase;std::map<std::uint64_t,std::uint64_t> previous_performer,previous_venue;
    J observe(const sim::World& world,std::uint64_t begin) {
        J observations=J::array();const auto& production=*world.original_production_state();
        if(production.culture)for(const auto& venue:production.culture->venues)if(venue.last_arrival&&venue.last_arrival->arrival_tick>begin)accepted_performers.insert(uid(venue.last_arrival->performer_id));
        for(const auto& witness:production.services.witnesses)if(witness.arrival_tick>begin&&witness.venue_walker&&witness.venue_walker->arrival_music)granted_venue_walkers.insert(uid(witness.venue_walker->walker_id));
        for(const auto& c:world.couriers()) {
            const auto id=uid(c.id);const auto role=static_cast<unsigned>(c.role);const auto name=std::to_string(role);auto& row=roles[name];
            if(row.is_null())row={{"idle",0U},{"outward",0U},{"returning",0U},{"edge_zero",0U},{"begun_edge",0U},{"route_wait",0U},{"directions",J::array({0U,0U,0U,0U})},{"phase_transitions",0U}};
            const bool idle=c.phase==sim::CourierPhase::IdleAtWorkshop;
            const char* phase=idle?"idle":(c.phase==sim::CourierPhase::Returning?"returning":"outward");row[phase]=row[phase].get<std::uint64_t>()+1;
            if(!idle){moving.insert(role);const char* edge=c.edge_progress==0?"edge_zero":"begun_edge";row[edge]=row[edge].get<std::uint64_t>()+1;if(c.route_pending)row["route_wait"]=row["route_wait"].get<std::uint64_t>()+1;if(const auto d=direction(c)){auto& n=row["directions"][assets::direction_index(*d)];n=n.get<std::uint64_t>()+1;}}
            const auto identity=actor_identity(world,c);const auto performer=identity.value("performer_id",std::uint64_t(0)),venue=identity.value("venue_walker_id",std::uint64_t(0));
            if(previous_phase.contains(id)&&previous_phase[id]!=c.phase){row["phase_transitions"]=row["phase_transitions"].get<std::uint64_t>()+1;if(idle){if(previous_performer[id])retired_performers.insert(previous_performer[id]);if(previous_phase[id]==sim::CourierPhase::Returning&&previous_venue[id])retired_venue_walkers.insert(previous_venue[id]);}}
            previous_phase[id]=c.phase;previous_performer[id]=performer;previous_venue[id]=venue;
            observations.push_back({{"courier",id},{"role",role},{"phase",static_cast<unsigned>(c.phase)},{"actual_assigned_workers",world.workers_assigned(c.owner)},{"owner_operating",world.building(c.owner).operating_enabled}});
        }
        return observations;
    }
    J report()const{return {{"actual_role_tick_counts",roles},{"moving_CourierRoles",moving},{"new_accepted_performer_ids",accepted_performers},{"new_actual_House_Music_grant_VenueWalkerIds",granted_venue_walkers},{"actual_performer_channel_retirements",retired_performers},{"actual_venue_return_then_idle_retirements",retired_venue_walkers}};}
};
J normal_staffing_commands(oe::SandboxView& view) {
    // Borrowed World spans never survive execute(): collect typed owning IDs first.
    std::vector<sim::BuildingId> pause_ids;
    for(const auto& b:view.world().buildings())if(b.placed&&b.operating_enabled)switch(b.kind){
    case sim::Object::OriginalLoggingShed38:case sim::Object::OriginalBronzeSmelter39:case sim::Object::OriginalBronzewareMaker42:case sim::Object::OriginalLacquerwareMaker44:case sim::Object::OriginalTeaCuringShed237:case sim::Object::OriginalLacquerRefinery238:case sim::Object::OriginalSilkwormShed239:pause_ids.push_back(b.id);break;
    default:break;}
    J rows=J::array();for(const auto id:pause_ids){const auto before=view.world().snapshot();const auto result=view.execute(sim::set_building_operation(id,false));check(result.accepted&&result.changed,"Normal paid QA staffing pause refused");const auto after=view.world().snapshot();check(after.ticks==before.ticks&&after.treasury==before.treasury&&after.construction_spent_total==before.construction_spent_total&&after.command_sequence==before.command_sequence+1,"Operation pause changed time/funds or command sequence");check(!view.world().building(id).operating_enabled,"Accepted pause did not change actual operation");rows.push_back({{"building",uid(id)},{"accepted",result.accepted},{"changed",result.changed},{"sequence",result.sequence},{"tick",result.tick},{"reason",result.reason},{"cost",0}});}
    return rows;
}
